<?php
declare(strict_types=1);
require_once dirname(__DIR__,2).'/src/bootstrap.php';require_admin();require_once dirname(__DIR__,2).'/src/admin_layout.php';
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$id=filter_var($_POST['id']??null,FILTER_VALIDATE_INT);$action=(string)($_POST['action']??'');
 if(!$id||!in_array($action,['read','unread','delete'],true)){flash('error','Invalid message action.');redirect('admin/messages.php');}
 if($action==='delete'){$s=db()->prepare('DELETE FROM messages WHERE id=?');$s->execute([$id]);flash('success','Message deleted.');redirect('admin/messages.php');}
 $s=db()->prepare('UPDATE messages SET is_read=? WHERE id=?');$s->execute([$action==='read'?1:0,$id]);flash('success','Message status updated.');redirect('admin/messages.php?id='.$id);
}
$id=filter_var($_GET['id']??null,FILTER_VALIDATE_INT);$selected=null;if($id){$s=db()->prepare('SELECT * FROM messages WHERE id=?');$s->execute([$id]);$selected=$s->fetch();}
$list=db()->query('SELECT id,name,email,subject,is_read,created_at FROM messages ORDER BY created_at DESC')->fetchAll();
admin_header('messages.php','Messages');
?><section class="admin-card"><h2>Inbox (<?= count($list) ?>)</h2><?php if(!$list): ?><p class="muted">No messages yet.</p><?php else: ?><table class="admin-table"><thead><tr><th>Sender</th><th>Subject</th><th>Date</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($list as $m): ?><tr class="<?= $m['is_read']?'':'unread' ?>"><td><?= e($m['name']) ?><br><a class="admin-link" href="mailto:<?= e($m['email']) ?>"><?= e($m['email']) ?></a></td><td><a class="admin-link" href="?id=<?= (int)$m['id'] ?>"><?= e($m['subject']) ?></a></td><td><?= e($m['created_at']) ?></td><td><?= $m['is_read']?'Read':'Unread' ?></td><td><div class="admin-actions"><form class="inline-form" method="post"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$m['id'] ?>"><button class="btn btn-small" name="action" value="<?= $m['is_read']?'unread':'read' ?>"><?= $m['is_read']?'Mark unread':'Mark read' ?></button></form><form class="inline-form" method="post" onsubmit="return confirm('Delete this message?')"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$m['id'] ?>"><button class="btn btn-small danger" name="action" value="delete">Delete</button></form></div></td></tr><?php endforeach; ?></tbody></table><?php endif; ?></section><?php if($selected): ?><section class="admin-card" style="margin-top:1rem"><h2><?= e($selected['subject']) ?></h2><p class="muted">From <?= e($selected['name']) ?> &lt;<a class="admin-link" href="mailto:<?= e($selected['email']) ?>"><?= e($selected['email']) ?></a>&gt; · <?= e($selected['created_at']) ?></p><hr style="margin:1rem 0"><p><?= nl2br(e($selected['message'])) ?></p></section><?php endif; ?><?php admin_footer(); ?>
